-- C01.4: only curated summaries bound to exact immutable reviewed versions.
create table public.feture_test_share_templates(
 version_id uuid not null references public.feture_test_versions(id),dimension_id text not null,
 title text not null check(length(title) between 1 and 120),summaries jsonb not null,
 enabled boolean not null default true,primary key(version_id,dimension_id),
 check(jsonb_typeof(summaries)='object' and summaries ?& array['low','mid','high']));
create table public.feture_test_share_operations(
 account_hash text not null references public.feture_profiles(account_hash) on delete cascade,
 operation_id uuid not null,payload_hash text not null,post_id uuid not null references public.feture_posts(id),
 attempt_id uuid not null,selected jsonb not null,consent_version text not null check(consent_version='selected-summary-v1'),
 created_at timestamptz not null default clock_timestamp(),primary key(account_hash,operation_id));
alter table public.feture_test_share_templates enable row level security;
alter table public.feture_test_share_operations enable row level security;
revoke all on public.feture_test_share_templates,public.feture_test_share_operations from public,anon,authenticated;
grant select on public.feture_test_share_templates to service_role;
grant select,insert on public.feture_test_share_operations to service_role;
insert into public.feture_test_share_templates(version_id,dimension_id,title,summaries) select id,'initiative','Инициатива','{"low": "Мне сейчас ближе откликаться на предложения.", "mid": "Мне подходит менять инициативу по ситуации.", "high": "Мне сейчас интересно проявлять инициативу."}'::jsonb from public.feture_test_versions where definition='{"id": "dynamics", "title": "Роли и динамика", "description": "Как тебе комфортнее распределять инициативу и договорённости. Любой вопрос можно пропустить. Это опросник для размышления, а не научная диагностика.", "dimensions": [{"id": "initiative", "title": "Инициатива", "low": "Тебе может быть комфортнее откликаться на предложения. Это не обязанность оставаться в одной роли.", "mid": "Похоже, инициатива зависит от ситуации. Можно обсудить, когда хочется предлагать, а когда — откликаться.", "high": "В ответах заметен интерес проявлять инициативу. Это не даёт права решать за другого человека."}, {"id": "agreement", "title": "Ясность договорённостей", "low": "Тебе может подходить меньше заранее заданных правил. Даже при спонтанности нужно обсуждать согласие и право остановиться.", "mid": "Тебе может подходить сочетание договорённостей и свободы. Полезно заранее назвать то, что менять нельзя.", "high": "В ответах важна ясность ожиданий. Подробные договорённости могут помогать комфорту, но не заменяют согласие в моменте."}], "questions": [{"id": "initiative-1", "prompt": "Мне нравится предлагать, как провести время вместе.", "dimension": "initiative", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "initiative-2", "prompt": "Мне комфортно первым начинать разговор о желаниях.", "dimension": "initiative", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "initiative-3", "prompt": "Мне интересно задавать направление совместному исследованию.", "dimension": "initiative", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "initiative-4", "prompt": "Мне удобно первым предлагать несколько вариантов на выбор, оставляя решение общим.", "dimension": "initiative", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "agreement-1", "prompt": "Мне спокойнее, когда ожидания обсуждены заранее.", "dimension": "agreement", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "agreement-2", "prompt": "Мне важно заранее понимать, что можно остановить без объяснения причин.", "dimension": "agreement", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "agreement-3", "prompt": "Я предпочитаю проговаривать, кто за что отвечает.", "dimension": "agreement", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "agreement-4", "prompt": "Перед новым опытом мне хочется обсудить возможные изменения плана.", "dimension": "agreement", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}]}'::jsonb;
insert into public.feture_test_share_templates(version_id,dimension_id,title,summaries) select id,'connection','Эмоциональная связь','{"low": "Мне сейчас удобнее спокойный эмоциональный обмен.", "mid": "Мне подходит менять степень близости по ситуации.", "high": "Мне сейчас важна эмоциональная связь."}'::jsonb from public.feture_test_versions where definition='{"id": "closeness", "title": "Близость и пространство", "description": "Что помогает ощущать связь, сохраняя комфортную дистанцию. Любой вопрос можно пропустить. Это опросник для размышления, а не научная диагностика.", "dimensions": [{"id": "connection", "title": "Эмоциональная связь", "low": "В ответах сейчас меньше потребности в частом эмоциональном обмене. Можно искать удобные способы связи без давления.", "mid": "Похоже, степень близости зависит от ситуации. Стоит обсудить, какие проявления поддержки подходят именно тебе.", "high": "В ответах заметна потребность в эмоциональной связи. Другой человек может проявлять её иначе; лучше назвать конкретные ожидания."}, {"id": "space", "title": "Личное пространство", "low": "Сейчас отдельное время может быть менее значимым для тебя. Это не означает, что у тебя нет границ.", "mid": "Похоже, тебе нужен гибкий баланс совместного и личного времени. Его можно пересматривать.", "high": "В ответах важно личное пространство. Можно договориться о времени на себя без трактовки его как отвержения."}], "questions": [{"id": "connection-1", "prompt": "Мне важно регулярно делиться переживаниями с близким человеком.", "dimension": "connection", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "connection-2", "prompt": "Тёплые слова помогают мне чувствовать связь.", "dimension": "connection", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "connection-3", "prompt": "Мне хочется обсуждать, как меняются наши отношения.", "dimension": "connection", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "connection-4", "prompt": "В сложный день я хочу иметь возможность попросить поддержки.", "dimension": "connection", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "space-1", "prompt": "Мне нужно время без общения, даже когда отношения хорошие.", "dimension": "space", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "space-2", "prompt": "Я хочу сохранять отдельные занятия и интересы.", "dimension": "space", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "space-3", "prompt": "Мне комфортнее заранее обсудить частоту общения.", "dimension": "space", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "space-4", "prompt": "Мне важно самостоятельно выбирать, чем делиться сегодня.", "dimension": "space", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}]}'::jsonb;
insert into public.feture_test_share_templates(version_id,dimension_id,title,summaries) select id,'novelty','Новизна','{"low": "Мне сейчас ближе знакомые впечатления.", "mid": "Мой интерес к новому зависит от ситуации.", "high": "Мне сейчас интересно узнавать новое."}'::jsonb from public.feture_test_versions where definition='{"id": "sensations", "title": "Ощущения и любопытство", "description": "Какие условия помогают исследовать ощущения без обязательства пробовать что-либо. Любой вопрос можно пропустить. Это опросник для размышления, а не научная диагностика.", "dimensions": [{"id": "novelty", "title": "Новизна", "low": "В ответах сейчас ближе знакомые ощущения. Нет необходимости расширять опыт ради чьих-то ожиданий.", "mid": "Интерес к новизне зависит от условий. Можно начать с разговора или наблюдения без обязательства действовать.", "high": "В ответах есть любопытство к новому. Оно не означает готовности к любой теме и не отменяет отдельных границ."}, {"id": "predictability", "title": "Предсказуемость", "low": "В ответах меньше потребности в подготовке. Полезно всё равно обозначать согласие, ограничения и возможность остановки.", "mid": "Тебе может подходить немного подготовки и возможность менять план. Стоит назвать условия, которые помогают расслабиться.", "high": "В ответах важны подготовка и предсказуемость. Можно заранее обсудить обстановку и темп без обязанности продолжать."}], "questions": [{"id": "novelty-1", "prompt": "Мне интересно узнавать о незнакомых ощущениях.", "dimension": "novelty", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "novelty-2", "prompt": "Мне нравится рассматривать разные способы совместного отдыха.", "dimension": "novelty", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "novelty-3", "prompt": "Я хочу иметь возможность попробовать новое и передумать.", "dimension": "novelty", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "novelty-4", "prompt": "Мне интересно обсуждать фантазии, даже если я не собираюсь их воплощать.", "dimension": "novelty", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "predictability-1", "prompt": "Мне спокойнее заранее понимать, как будет устроен новый опыт.", "dimension": "predictability", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "predictability-2", "prompt": "Для комфорта мне важно выбрать подходящее место и время.", "dimension": "predictability", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "predictability-3", "prompt": "Мне помогает начинать с небольших понятных шагов.", "dimension": "predictability", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "predictability-4", "prompt": "Мне хочется знать, что пауза не вызовет обиды или давления.", "dimension": "predictability", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}]}'::jsonb;
insert into public.feture_test_share_templates(version_id,dimension_id,title,summaries) select id,'gradual','Постепенность','{"low": "Мне сейчас подходит более быстрый темп.", "mid": "Мне подходит выбирать темп по ситуации.", "high": "Мне сейчас важно двигаться постепенно."}'::jsonb from public.feture_test_versions where definition='{"id": "pace", "title": "Темп и готовность", "description": "Какой темп знакомства и новых шагов может быть комфортен сейчас. Любой вопрос можно пропустить. Это опросник для размышления, а не научная диагностика.", "dimensions": [{"id": "gradual", "title": "Постепенность", "low": "В ответах меньше потребности в длинной подготовке. Даже быстрый темп требует взаимной готовности и возможности остановки.", "mid": "Темп может зависеть от ситуации. Удобно договориться о небольшом следующем шаге без обещания продолжения.", "high": "В ответах важна постепенность. Можно начать с беседы и дать себе время без сравнений с чужим темпом."}, {"id": "checkin", "title": "Проверка готовности", "low": "Сейчас частые уточнения могут быть менее удобны. Это не означает согласия заранее: готовность нужно уточнять перед конкретным действием.", "mid": "Может подходить проверка готовности в важных точках. Можно обсудить удобный способ задавать вопросы.", "high": "В ответах важны регулярные уточнения готовности. Можно согласовать их так, чтобы они поддерживали комфорт, а не создавали давление."}], "questions": [{"id": "gradual-1", "prompt": "Мне комфортнее узнавать человека постепенно.", "dimension": "gradual", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "gradual-2", "prompt": "Перед новым шагом мне хочется время на обдумывание.", "dimension": "gradual", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "gradual-3", "prompt": "Мне нравится двигаться небольшими шагами.", "dimension": "gradual", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "gradual-4", "prompt": "Я предпочитаю возвращаться к разговору после паузы.", "dimension": "gradual", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "checkin-1", "prompt": "Мне помогает вопрос о готовности перед новым шагом.", "dimension": "checkin", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "checkin-2", "prompt": "Я хочу иметь возможность изменить решение без чувства вины.", "dimension": "checkin", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "checkin-3", "prompt": "Мне важно отличать интерес к теме от готовности действовать.", "dimension": "checkin", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}, {"id": "checkin-4", "prompt": "Я предпочитаю обсуждать, что делать, если комфорт изменится.", "dimension": "checkin", "kind": "scale", "options": [{"id": "answer-0", "label": "Сейчас не подходит", "score": 0}, {"id": "answer-1", "label": "Скорее не подходит", "score": 1}, {"id": "answer-2", "label": "Зависит от ситуации", "score": 2}, {"id": "answer-3", "label": "Скорее подходит", "score": 3}, {"id": "answer-4", "label": "Сейчас подходит", "score": 4}]}]}'::jsonb;

create function public.feture_test_share_command(p_actor text,p_command jsonb) returns jsonb
language plpgsql security invoker set search_path=pg_catalog,public as $$
declare
 act text:=p_command->>'action';keys text[];a public.feture_test_attempts%rowtype;
 items jsonb;projection jsonb;projection_hash text;selected jsonb;body text;result jsonb;
 receipt public.feture_test_share_operations%rowtype;p public.feture_posts%rowtype;h text;op uuid;
begin
 if p_actor is null or p_actor !~ '^[a-f0-9]{32}$' or jsonb_typeof(p_command) is distinct from 'object' then return jsonb_build_object('ok',false,'error','invalid_request');end if;
 select array_agg(k order by k) into keys from jsonb_object_keys(p_command) k;
 if act='posts.testPreview' then
  if keys is distinct from array['action','attemptId']::text[] then return jsonb_build_object('ok',false,'error','invalid_request');end if;
 elsif act='posts.fromTest' then
  if keys is distinct from array['action','attemptId','authorLabel','consent','expectedAttemptRevision','id','operationId','plannedAudience','projectionHash','recipientCodes','selected','versionId']::text[]
   or p_command->'consent' is distinct from 'true'::jsonb
   or jsonb_typeof(p_command->'selected') is distinct from 'array' then return jsonb_build_object('ok',false,'error','invalid_request');end if;
  if jsonb_array_length(p_command->'selected') not between 1 and 4
   or exists(select 1 from jsonb_array_elements(p_command->'selected') x where jsonb_typeof(x)<>'string' or (x#>>'{}') !~ '^[a-z][a-z0-9-]{0,47}$')
   or (select count(distinct x) from jsonb_array_elements(p_command->'selected') x)<>jsonb_array_length(p_command->'selected')
   or jsonb_typeof(p_command->'expectedAttemptRevision') is distinct from 'number'
   or (p_command->>'expectedAttemptRevision') !~ '^[1-9][0-9]{0,14}$'
   or jsonb_typeof(p_command->'projectionHash') is distinct from 'string' or (p_command->>'projectionHash') !~ '^[a-f0-9]{64}$'
   or jsonb_typeof(p_command->'id') is distinct from 'string' or jsonb_typeof(p_command->'operationId') is distinct from 'string' or jsonb_typeof(p_command->'versionId') is distinct from 'string'
   or (p_command->>'id') !~ '^[a-f0-9-]{36}$' or (p_command->>'operationId') !~ '^[a-f0-9-]{36}$'
   or (p_command->>'versionId') !~ '^[a-f0-9-]{36}$' then return jsonb_build_object('ok',false,'error','invalid_request');end if;
 else return jsonb_build_object('ok',false,'error','invalid_request');end if;
 if jsonb_typeof(p_command->'attemptId') is distinct from 'string' or (p_command->>'attemptId') !~ '^[a-f0-9-]{36}$' then return jsonb_build_object('ok',false,'error','invalid_request');end if;
 -- Same owner lock as tests.complete/delete; the post lock order is owner -> profile.
 perform pg_advisory_xact_lock(hashtextextended('feture-tests-owner:'||p_actor,0));
 if not public.feture_peer_eligible(p_actor) then return jsonb_build_object('ok',false,'error','resource_not_found');end if;
 if act='posts.fromTest' then
  perform 1 from public.feture_profiles where account_hash=p_actor for update;
  op:=(p_command->>'operationId')::uuid;h:=encode(sha256(convert_to(p_command::text,'UTF8')),'hex');
  select * into receipt from public.feture_test_share_operations where account_hash=p_actor and operation_id=op;
  if receipt.operation_id is not null then
   if receipt.payload_hash<>h then return jsonb_build_object('ok',false,'error','operation_conflict');end if;
   select * into p from public.feture_posts where id=receipt.post_id and author_hash=p_actor;
   if p.id is null then return jsonb_build_object('ok',false,'error','resource_not_found');end if;
   return jsonb_build_object('ok',true,'entry',public.feture_post_dto(p,true),'replayed',true);
  end if;
  if exists(select 1 from public.feture_post_operations where account_hash=p_actor and operation_id=op)
   or exists(select 1 from public.feture_posts where id=(p_command->>'id')::uuid) then return jsonb_build_object('ok',false,'error','operation_conflict');end if;
 end if;
 select * into a from public.feture_test_attempts where id=(p_command->>'attemptId')::uuid and account_hash=p_actor and status='completed';
 if a.id is null then return jsonb_build_object('ok',false,'error','resource_not_found');end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',t.dimension_id,'title',t.title,'summary',t.summaries->>(d->>'level')) order by t.dimension_id),'[]'::jsonb) into items
 from public.feture_test_share_templates t join lateral jsonb_array_elements(a.result->'dimensions') d on d->>'id'=t.dimension_id
 where t.version_id=a.version_id and t.enabled and d->>'level' in ('low','mid','high');
 projection:=jsonb_build_object('attemptId',a.id,'attemptRevision',a.revision,'versionId',a.version_id,'items',items);
 projection_hash:=encode(sha256(convert_to(projection::text,'UTF8')),'hex');
 if act='posts.testPreview' then return jsonb_build_object('ok',true,'preview',projection||jsonb_build_object('projectionHash',projection_hash));end if;
 if (p_command->>'expectedAttemptRevision')::bigint<>a.revision or (p_command->>'versionId')::uuid<>a.version_id
  or p_command->>'projectionHash'<>projection_hash then return jsonb_build_object('ok',false,'error','revision_conflict');end if;
 selected:=p_command->'selected';
 if exists(select 1 from jsonb_array_elements_text(selected) s where not exists(select 1 from jsonb_array_elements(items) x where x->>'id'=s)) then return jsonb_build_object('ok',false,'error','invalid_request');end if;
 select 'Выбранные выводы моего опросника:'||E'\n'||string_agg((x->>'title')||': '||(x->>'summary'),E'\n' order by x->>'id')||E'\n\nЭто мои ответы сейчас, не диагноз и не согласие на конкретный опыт.' into body
 from jsonb_array_elements(items) x where selected ? (x->>'id');
 result:=public.feture_post_command(p_actor,jsonb_build_object('action','posts.save','id',p_command->'id','operationId',p_command->'operationId','expectedRevision',0,'text',body,'kind','text','authorLabel',p_command->'authorLabel','plannedAudience',p_command->'plannedAudience','recipientCodes',p_command->'recipientCodes'));
 if result->'ok' is distinct from 'true'::jsonb then return result;end if;
 insert into public.feture_test_share_operations(account_hash,operation_id,payload_hash,post_id,attempt_id,selected,consent_version)
 values(p_actor,op,h,(p_command->>'id')::uuid,a.id,selected,'selected-summary-v1');
 return result;
exception when invalid_text_representation or numeric_value_out_of_range then return jsonb_build_object('ok',false,'error','invalid_request');
end $$;
revoke all on function public.feture_test_share_command(text,jsonb) from public,anon,authenticated;
grant execute on function public.feture_test_share_command(text,jsonb) to service_role;
